      corde_soie: { name: "Corde de soie", kind: "outil", bonus: { nature: 5 }, desc: "Trente pieds de soie tressée, de l'épaisseur d'un doigt, qui tiennent dans une poche et portent deux hommes." },
      passe_morts: { name: "Clef de fossoyeur", kind: "outil", bonus: { discretion: 5 }, desc: "Une clef plate, à panneton carré, que la Douairière tenait d'un mari. Elle ouvre les grilles de caveau de tout le pays, qui sont faites sur le même modèle par économie." },
